const rotear = $('Rotear').first().json;
const msg = $json.mensagem || rotear.mensagem;

let cliente = null;

// Tenta cliente existente (veio pelo caminho true)
const existente = $input.first().json;
if (existente?.id) {
  cliente = existente;
}

// Se não, tenta o criado (veio pelo caminho false → criar cliente)
if (!cliente) {
  try {
    const criado = $('criar cliente').first().json;
    const c = Array.isArray(criado) ? criado[0] : criado;
    if (c?.id) cliente = c;
  } catch(e) {}
}

return [{ json: { ...rotear, cliente_id: cliente?.id || null, cliente, mensagem: msg } }];

const barbeiros = $input.all().map(i => i.json);
const input = $('Edit Fields10').first().json;
const barbearia = $('barbearia1').first().json;

const tel = input.Telefone?.toString().replace(/\D/g,'').replace(/^55/,'') || '';

const barbeiro_atual = barbeiros.find(b => {
  const t = b.telefone?.toString().replace(/\D/g,'').replace(/^55/,'') || '';
  const s = t.length===11 ? t.slice(0,2)+t.slice(3) : t;
  const c = t.length===10 ? t.slice(0,2)+'9'+t.slice(2) : t;
  return t===tel || s===tel || c===tel;
}) || null;

return [{ json: {
  isBarbeiro: barbeiro_atual !== null,
  isDono: barbeiro_atual?.role === 'dono' || false,
  barbeiro_atual,
  barbearia_id: barbearia.id || null,
  barbearia_nome: barbearia.nome || null,
  instancia: barbearia.instance_name || null,
  Telefone: tel,
  Nome: input.Nome,
  mensagem: input.mensagem,
  tipoMensagem: input.tipoMensagem,
  id: input.id,
  barbeiros
}}];

const output = $json.output || '';
const dados = $('montar contexto barbeiro').first().json;
const hist = [
  ...(dados.historico||[]),
  { role:'user', content:dados.mensagem, ts:new Date().toISOString() },
  { role:'assistant', content:output, ts:new Date().toISOString() }
].slice(-20);
return [{ json: { ...dados, output, historicoAtualizado: hist } }];

